const markStalled = `-- name: MarkStalled :many
UPDATE dispatches SET updated_at = ?1, stalled_at = ?1
WHERE status = 'running' AND stalled_at IS NULL AND waiting_since IS NULL
  AND progress_at <= CAST(?2 AS INTEGER)
RETURNING id, node_id
`

type MarkStalledParams struct {
	Now            int64
	ProgressBefore int64
}

type MarkStalledRow struct {
	ID     string
	NodeID string
}

func (q *Queries) MarkStalled(ctx context.Context, arg MarkStalledParams) ([]MarkStalledRow, error) {
	rows, err := q.db.QueryContext(ctx, markStalled, arg.Now, arg.ProgressBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MarkStalledRow{}
	for rows.Next() {
		var i MarkStalledRow
		if err := rows.Scan(&i.ID, &i.NodeID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

